const events = require('../events');

const UserEmail = module.exports;

UserEmail.exists = async function (email) {
	const uid = await user.getUidByEmail(email.toLowerCase());
	return !!uid;
};

UserEmail.available = async function (email) {
	const exists = await db.isSortedSetMember('email:uid', email.toLowerCase());
	return !exists;
};

UserEmail.getConfirmation = async function (uid) {
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return null;
	}
	const confirmation = await db.getObject(`confirm:${code}`);
	return confirmation && parseInt(confirmation.uid, 10) === parseInt(uid, 10) ? confirmation : null;
};

UserEmail.isValidationPending = async function (uid, email) {
	const confirmation = await UserEmail.getConfirmation(uid);
	return !!(confirmation && confirmation.email && Number(confirmation.expires) > Date.now() &&
		(!email || confirmation.email.toLowerCase() === email.toLowerCase()));
};

UserEmail.getEmailForValidation = async function (uid) {
	const email = await user.getUserField(uid, 'email');
	if (email) {
		return email;
	}
	const confirmation = await UserEmail.getConfirmation(uid);
	return confirmation && confirmation.email ? confirmation.email : null;
};

UserEmail.expireValidation = async function (uid) {
	const code = await db.get(`confirm:byUid:${uid}`);
	await db.deleteAll([
		`confirm:byUid:${uid}`,
		`uid:${uid}:confirm:email:sent`,
		...(code ? [`confirm:${code}`] : []),
	]);
};

UserEmail.sendValidationEmail = async function (uid, options) {
	/*
	 * 	Options:
	 * 		- email, overrides email retrieval
	 * 		- force, sends email even if it is too soon to send another
	 */

	options = options || {};

	// Fallback behaviour (email passed in as second argument)
	if (typeof options === 'string') {
		options = {
			email: options,
		};
	}

	let confirm_code = utils.generateUUID();

	const emailInterval = meta.config.emailConfirmInterval;

	// If no email passed in (default), retrieve email from uid
	const currentEmail = await user.getUserField(uid, 'email');
	if (!options.email || !options.email.length) {
		options.email = await UserEmail.getEmailForValidation(uid);
	} else if (currentEmail && currentEmail.toLowerCase() === options.email.toLowerCase()) {
		throw new Error('[[error:email-nochange]]');
	}
	if (!options.email) {
		throw new Error('[[error:invalid-email]]');
	}
	if (!options.force && await UserEmail.isValidationPending(uid)) {
		throw new Error(`[[error:confirm-email-already-sent, ${emailInterval}]]`);
	}
	if (options.force || await db.get(`confirm:byUid:${uid}`)) {
